contracts/ElyAccount.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import {IERC1271} from "@openzeppelin/contracts/interfaces/IERC1271.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {SignatureChecker} from "@openzeppelin/contracts/utils/cryptography/SignatureChecker.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {IElyiaRouter} from "./interfaces/IElyiaRouter.sol";
import {IMorphoLike} from "./interfaces/IExternal.sol";

/// @title ElyAccount
/// @author Elyia
/// @notice Ely's bounded agent account. A minimal smart account owned by one user. The owner can do
///         anything and withdraw at any time. The owner may grant one AGENT key (the opt-in Ely keeper)
///         a policy: allowlisted (target, action) pairs, per-token per-transaction and daily caps, an
///         allowed-token set and an expiry. Agent actions are typed (swap via ElyiaRouter, ERC-4626
///         deposit/redeem, Morpho-style supply/withdraw); every output is forced back into this account.
/// @dev The agent can never: transfer or approve tokens, call arbitrary targets, change the policy,
///      sign ERC-1271 messages, or withdraw. Revocation bumps `policyEpoch`, which voids every
///      permission and cap at once. Deployed as EIP-1167 clones by ElyAccountFactory. NOT AUDITED.
contract ElyAccount is EIP712, ReentrancyGuard, IERC1271 {
    using SafeERC20 for IERC20;

    // ---------------------------------------------------------------------------------------------
    // Constants
    // ---------------------------------------------------------------------------------------------

    address internal constant NATIVE = address(0);

    /// @notice Action selectors an agent policy may allowlist on a target.
    bytes4 public constant ACTION_ROUTER_SWAP = IElyiaRouter.swap.selector;
    bytes4 public constant ACTION_VAULT_DEPOSIT = IERC4626.deposit.selector;
    bytes4 public constant ACTION_VAULT_REDEEM = IERC4626.redeem.selector;
    bytes4 public constant ACTION_LEND_SUPPLY = IMorphoLike.supply.selector;
    bytes4 public constant ACTION_LEND_WITHDRAW = IMorphoLike.withdraw.selector;

    /// @notice Replay-safe ERC-1271 wrapper: the owner signs `ElyAccountMessage(hash)` in this
    ///         account's EIP-712 domain, so a signature for one account never validates on another.
    bytes32 public constant MESSAGE_TYPEHASH = keccak256("ElyAccountMessage(bytes32 hash)");

    /// @notice The factory allowed to initialize clones.
    address public immutable factory;

    // ---------------------------------------------------------------------------------------------
    // Storage
    // ---------------------------------------------------------------------------------------------

    /// @notice The account owner. Fixed at creation.
    address public owner;
    /// @notice Current agent key, `address(0)` when none.
    address public agent;
    /// @notice Agent powers end after this unix time.
    uint64 public agentValidUntil;
    /// @notice Bumped on every policy change or revocation; old permissions live under old epochs.
    uint64 public policyEpoch;
    bool private _initialized;

    struct TokenRule {
        address token; // address(0) = native HYPE
        uint128 perTxCap; // max the agent may spend in one action (0 = receive-only)
        uint128 dailyCap; // max the agent may spend per UTC day
    }

    struct CallRule {
        address target;
        bytes4 action; // one of the ACTION_* selectors
    }

    struct Limit {
        bool allowed;
        uint128 perTxCap;
        uint128 dailyCap;
    }

    struct Spend {
        uint64 day;
        uint192 amount;
    }

    mapping(uint64 epoch => mapping(address target => mapping(bytes4 action => bool))) internal _callAllowed;
    mapping(uint64 epoch => mapping(address token => Limit)) internal _limit;
    mapping(uint64 epoch => mapping(address token => Spend)) internal _spent;
    /// @dev Morpho-style markets are permissionless; lending is pinned to owner-approved market ids.
    mapping(uint64 epoch => mapping(bytes32 marketId => bool)) internal _marketAllowed;

    // ---------------------------------------------------------------------------------------------
    // Events
    // ---------------------------------------------------------------------------------------------

    event Initialized(address indexed owner);
    event Executed(address indexed target, uint256 value, bytes4 selector);
    event Withdrawn(address indexed token, address indexed to, uint256 amount);
    event AgentPolicySet(address indexed agent, uint64 validUntil, uint64 indexed epoch);
    event AgentCallAllowed(uint64 indexed epoch, address indexed target, bytes4 action);
    event AgentTokenRule(uint64 indexed epoch, address indexed token, uint128 perTxCap, uint128 dailyCap);
    event AgentMarketAllowed(uint64 indexed epoch, bytes32 indexed marketId);
    event AgentRevoked(address indexed agent, uint64 indexed epoch);
    /// @notice Audit log of every agent action.
    event AgentAction(
        address indexed agent,
        bytes4 indexed action,
        address indexed target,
        address tokenIn,
        uint256 amountIn,
        address tokenOut,
        uint256 amountOut
    );

    // ---------------------------------------------------------------------------------------------
    // Errors
    // ---------------------------------------------------------------------------------------------

    error NotOwner();
    error NotAgent();
    error AlreadyInitialized();
    error NotFactory();
    error ZeroAddress();
    error BadPolicy();
    error CallNotAllowed(address target, bytes4 action);
    error TokenNotAllowed(address token);
    error PerTxCapExceeded(address token, uint256 amount, uint256 cap);
    error DailyCapExceeded(address token, uint256 spent, uint256 cap);
    error BadRecipient();
    error IntegratorFeeNotAllowed();
    error InsufficientOutput(uint256 amountOut, uint256 minAmountOut);
    error OverSpent(address token, uint256 spent, uint256 allowed);
    error NativeTransferFailed();
    error LengthMismatch();
    error MarketNotAllowed(bytes32 marketId);

    // ---------------------------------------------------------------------------------------------
    // Construction (implementation) and initialization (clones)
    // ---------------------------------------------------------------------------------------------

    constructor(address factory_) EIP712("ElyAccount", "1") {
        factory = factory_;
        // Lock the implementation itself.
        _initialized = true;
    }

    /// @notice Called once by the factory in the same transaction that creates the clone.
    function initialize(address owner_) external {
        if (msg.sender != factory) revert NotFactory();
        if (_initialized) revert AlreadyInitialized();
        if (owner_ == address(0)) revert ZeroAddress();
        _initialized = true;
        owner = owner_;
        emit Initialized(owner_);
    }

    receive() external payable {}

    // ---------------------------------------------------------------------------------------------
    // Modifiers
    // ---------------------------------------------------------------------------------------------

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier onlyAgent() {
        if (msg.sender != agent || msg.sender == address(0) || block.timestamp > agentValidUntil) revert NotAgent();
        _;
    }

    // ---------------------------------------------------------------------------------------------
    // Owner powers
    // ---------------------------------------------------------------------------------------------

    /// @notice Arbitrary call by the owner.
    function execute(address target, uint256 value, bytes calldata data)
        external
        payable
        onlyOwner
        nonReentrant
        returns (bytes memory result)
    {
        result = _call(target, value, data);
    }

    /// @notice Arbitrary batch of calls by the owner.
    function executeBatch(address[] calldata targets, uint256[] calldata values, bytes[] calldata data)
        external
        payable
        onlyOwner
        nonReentrant
    {
        if (targets.length != values.length || targets.length != data.length) revert LengthMismatch();
        for (uint256 i; i < targets.length; ++i) {
            _call(targets[i], values[i], data[i]);
        }
    }

    /// @notice Withdraw `amount` of `token` (address(0) = HYPE) to the owner. Always available.
    function withdraw(address token, uint256 amount) external onlyOwner nonReentrant {
        _sendToOwner(token, amount);
    }

    /// @notice Withdraw the whole balance of each token to the owner.
    function withdrawAll(address[] calldata tokens) external onlyOwner nonReentrant {
        for (uint256 i; i < tokens.length; ++i) {
            address t = tokens[i];
            uint256 bal = t == NATIVE ? address(this).balance : IERC20(t).balanceOf(address(this));
            if (bal != 0) _sendToOwner(t, bal);
        }
    }

    /// @notice Replace the agent policy. Voids every previous permission, cap and spend counter.
    /// @param agent_ The agent key.
    /// @param validUntil Expiry (unix seconds), must be in the future.
    /// @param calls Allowlisted (target, action) pairs.
    /// @param tokens Allowed tokens with caps; a token the agent may receive but not spend has caps 0.
    /// @param markets Morpho-style market ids (keccak256(abi.encode(MarketParams))) the agent may lend to.
    function setAgentPolicy(
        address agent_,
        uint64 validUntil,
        CallRule[] calldata calls,
        TokenRule[] calldata tokens,
        bytes32[] calldata markets
    )
        external
        onlyOwner
        nonReentrant
    {
        if (agent_ == address(0) || agent_ == address(this) || agent_ == owner) revert BadPolicy();
        if (validUntil <= block.timestamp) revert BadPolicy();
        uint64 epoch = ++policyEpoch;
        agent = agent_;
        agentValidUntil = validUntil;
        emit AgentPolicySet(agent_, validUntil, epoch);

        for (uint256 i; i < calls.length; ++i) {
            CallRule calldata c = calls[i];
            if (c.target == address(0) || c.target == address(this) || c.target.code.length == 0) revert BadPolicy();
            if (!_isAction(c.action)) revert BadPolicy();
            _callAllowed[epoch][c.target][c.action] = true;
            emit AgentCallAllowed(epoch, c.target, c.action);
        }
        for (uint256 i; i < tokens.length; ++i) {
            TokenRule calldata t = tokens[i];
            if (t.perTxCap > t.dailyCap) revert BadPolicy();
            _limit[epoch][t.token] = Limit({allowed: true, perTxCap: t.perTxCap, dailyCap: t.dailyCap});
            emit AgentTokenRule(epoch, t.token, t.perTxCap, t.dailyCap);
        }
        for (uint256 i; i < markets.length; ++i) {
            _marketAllowed[epoch][markets[i]] = true;
            emit AgentMarketAllowed(epoch, markets[i]);
        }
    }

    /// @notice Instantly revoke the agent and every permission.
    function revokeAgent() external onlyOwner {
        address old = agent;
        uint64 epoch = ++policyEpoch;
        agent = address(0);
        agentValidUntil = 0;
        emit AgentRevoked(old, epoch);
    }

    // ---------------------------------------------------------------------------------------------
    // Agent powers (bounded)
    // ---------------------------------------------------------------------------------------------

    /// @notice Swap through an allowlisted ElyiaRouter. Recipient must be this account; no integrator fee.
    function agentSwap(address router, IElyiaRouter.SwapParams calldata params)
        external
        onlyAgent
        nonReentrant
        returns (uint256 amountOut)
    {
        _requireCall(router, ACTION_ROUTER_SWAP);
        if (params.recipient != address(this)) revert BadRecipient();
        if (params.integrator != address(0) || params.integratorFeeBps != 0) revert IntegratorFeeNotAllowed();
        _requireAllowedToken(params.tokenOut);
        _spend(params.tokenIn, params.amountIn);

        uint256 inBefore = _balance(params.tokenIn);
        uint256 outBefore = _balance(params.tokenOut);
        if (params.tokenIn == NATIVE) {
            IElyiaRouter(router).swap{value: params.amountIn}(params);
        } else {
            IERC20(params.tokenIn).forceApprove(router, params.amountIn);
            IElyiaRouter(router).swap(params);
            IERC20(params.tokenIn).forceApprove(router, 0);
        }
        amountOut = _checkFlows(params.tokenIn, inBefore, params.amountIn, params.tokenOut, outBefore, params.minAmountOut);
        emit AgentAction(
            msg.sender, ACTION_ROUTER_SWAP, router, params.tokenIn, params.amountIn, params.tokenOut, amountOut
        );
    }

    /// @notice Deposit into an allowlisted ERC-4626 vault; shares go to this account.
    function agentVaultDeposit(address vault, uint256 assets, uint256 minShares)
        external
        onlyAgent
        nonReentrant
        returns (uint256 shares)
    {
        _requireCall(vault, ACTION_VAULT_DEPOSIT);
        address asset = IERC4626(vault).asset();
        _requireAllowedToken(vault);
        _spend(asset, assets);

        uint256 inBefore = _balance(asset);
        uint256 outBefore = _balance(vault);
        IERC20(asset).forceApprove(vault, assets);
        IERC4626(vault).deposit(assets, address(this));
        IERC20(asset).forceApprove(vault, 0);
        shares = _checkFlows(asset, inBefore, assets, vault, outBefore, minShares);
        emit AgentAction(msg.sender, ACTION_VAULT_DEPOSIT, vault, asset, assets, vault, shares);
    }

    /// @notice Redeem shares of an allowlisted ERC-4626 vault; assets come back to this account.
    function agentVaultRedeem(address vault, uint256 shares, uint256 minAssets)
        external
        onlyAgent
        nonReentrant
        returns (uint256 assets)
    {
        _requireCall(vault, ACTION_VAULT_REDEEM);
        address asset = IERC4626(vault).asset();
        _requireAllowedToken(asset);
        _spend(vault, shares);

        uint256 inBefore = _balance(vault);
        uint256 outBefore = _balance(asset);
        IERC4626(vault).redeem(shares, address(this), address(this));
        assets = _checkFlows(vault, inBefore, shares, asset, outBefore, minAssets);
        emit AgentAction(msg.sender, ACTION_VAULT_REDEEM, vault, vault, shares, asset, assets);
    }

    /// @notice Supply the loan token to an allowlisted Morpho-style market on behalf of this account.
    function agentLendSupply(address morpho, IMorphoLike.MarketParams calldata market, uint256 assets)
        external
        onlyAgent
        nonReentrant
        returns (uint256 supplied)
    {
        _requireCall(morpho, ACTION_LEND_SUPPLY);
        _requireMarket(market);
        _spend(market.loanToken, assets);
        uint256 before = _balance(market.loanToken);
        IERC20(market.loanToken).forceApprove(morpho, assets);
        IMorphoLike(morpho).supply(market, assets, 0, address(this), "");
        IERC20(market.loanToken).forceApprove(morpho, 0);
        supplied = before - _balance(market.loanToken);
        if (supplied > assets) revert OverSpent(market.loanToken, supplied, assets);
        emit AgentAction(msg.sender, ACTION_LEND_SUPPLY, morpho, market.loanToken, supplied, address(0), 0);
    }

    /// @notice Withdraw from an allowlisted Morpho-style market; assets always return to this account.
    function agentLendWithdraw(address morpho, IMorphoLike.MarketParams calldata market, uint256 assets, uint256 shares)
        external
        onlyAgent
        nonReentrant
        returns (uint256 withdrawn)
    {
        _requireCall(morpho, ACTION_LEND_WITHDRAW);
        _requireMarket(market);
        _requireAllowedToken(market.loanToken);
        uint256 before = _balance(market.loanToken);
        IMorphoLike(morpho).withdraw(market, assets, shares, address(this), address(this));
        withdrawn = _balance(market.loanToken) - before;
        if (withdrawn == 0) revert InsufficientOutput(0, 1);
        emit AgentAction(msg.sender, ACTION_LEND_WITHDRAW, morpho, address(0), 0, market.loanToken, withdrawn);
    }

    // ---------------------------------------------------------------------------------------------
    // ERC-1271 (owner only, replay-safe)
    // ---------------------------------------------------------------------------------------------

    /// @notice EIP-712 digest the owner signs to approve `hash` for this account.
    function replaySafeHash(bytes32 hash) public view returns (bytes32) {
        return _hashTypedDataV4(keccak256(abi.encode(MESSAGE_TYPEHASH, hash)));
    }

    /// @inheritdoc IERC1271
    /// @dev Only the owner's signature over `replaySafeHash(hash)` is valid. The agent can never sign.
    function isValidSignature(bytes32 hash, bytes calldata signature) external view returns (bytes4) {
        address o = owner;
        if (o != address(0) && SignatureChecker.isValidSignatureNow(o, replaySafeHash(hash), signature)) {
            return IERC1271.isValidSignature.selector;
        }
        return 0xffffffff;
    }

    // ---------------------------------------------------------------------------------------------
    // Views
    // ---------------------------------------------------------------------------------------------

    /// @notice True when the current agent may call `action` on `target`.
    function isCallAllowed(address target, bytes4 action) external view returns (bool) {
        return _callAllowed[policyEpoch][target][action];
    }

    /// @notice Current rule for `token` and how much the agent already spent today.
    function tokenRule(address token)
        external
        view
        returns (bool allowed, uint128 perTxCap, uint128 dailyCap, uint256 spentToday)
    {
        uint64 epoch = policyEpoch;
        Limit memory lim = _limit[epoch][token];
        Spend memory s = _spent[epoch][token];
        spentToday = s.day == uint64(block.timestamp / 1 days) ? s.amount : 0;
        return (lim.allowed, lim.perTxCap, lim.dailyCap, spentToday);
    }

    /// @notice True when the current agent may lend to `marketId`.
    function isMarketAllowed(bytes32 marketId) external view returns (bool) {
        return _marketAllowed[policyEpoch][marketId];
    }

    /// @notice True when an agent is set and not expired.
    function agentActive() external view returns (bool) {
        return agent != address(0) && block.timestamp <= agentValidUntil;
    }

    // ---------------------------------------------------------------------------------------------
    // Internals
    // ---------------------------------------------------------------------------------------------

    function _isAction(bytes4 a) internal pure returns (bool) {
        return a == ACTION_ROUTER_SWAP || a == ACTION_VAULT_DEPOSIT || a == ACTION_VAULT_REDEEM
            || a == ACTION_LEND_SUPPLY || a == ACTION_LEND_WITHDRAW;
    }

    function _requireCall(address target, bytes4 action) internal view {
        if (!_callAllowed[policyEpoch][target][action]) revert CallNotAllowed(target, action);
    }

    function _requireMarket(IMorphoLike.MarketParams calldata market) internal view {
        bytes32 id = keccak256(abi.encode(market));
        if (!_marketAllowed[policyEpoch][id]) revert MarketNotAllowed(id);
    }

    function _requireAllowedToken(address token) internal view {
        if (!_limit[policyEpoch][token].allowed) revert TokenNotAllowed(token);
    }

    /// @dev Charges `amount` of `token` against the per-tx and daily caps of the current epoch.
    function _spend(address token, uint256 amount) internal {
        uint64 epoch = policyEpoch;
        Limit memory lim = _limit[epoch][token];
        if (!lim.allowed) revert TokenNotAllowed(token);
        if (amount > lim.perTxCap) revert PerTxCapExceeded(token, amount, lim.perTxCap);
        uint64 day = uint64(block.timestamp / 1 days);
        Spend storage s = _spent[epoch][token];
        uint256 already = s.day == day ? s.amount : 0;
        uint256 total = already + amount;
        if (total > lim.dailyCap) revert DailyCapExceeded(token, total, lim.dailyCap);
        s.day = day;
        s.amount = uint192(total);
    }

    /// @dev Verifies the account spent at most `maxIn` of `tokenIn` and received >= `minOut` of `tokenOut`.
    function _checkFlows(
        address tokenIn,
        uint256 inBefore,
        uint256 maxIn,
        address tokenOut,
        uint256 outBefore,
        uint256 minOut
    ) internal view returns (uint256 received) {
        uint256 inAfter = _balance(tokenIn);
        uint256 spent = inBefore > inAfter ? inBefore - inAfter : 0;
        if (spent > maxIn) revert OverSpent(tokenIn, spent, maxIn);
        uint256 outAfter = _balance(tokenOut);
        received = outAfter > outBefore ? outAfter - outBefore : 0;
        if (received == 0 || received < minOut) revert InsufficientOutput(received, minOut);
    }

    function _balance(address token) internal view returns (uint256) {
        return token == NATIVE ? address(this).balance : IERC20(token).balanceOf(address(this));
    }

    function _call(address target, uint256 value, bytes calldata data) internal returns (bytes memory result) {
        bool ok;
        (ok, result) = target.call{value: value}(data);
        if (!ok) {
            assembly ("memory-safe") {
                revert(add(result, 32), mload(result))
            }
        }
        emit Executed(target, value, data.length >= 4 ? bytes4(data[:4]) : bytes4(0));
    }

    function _sendToOwner(address token, uint256 amount) internal {
        address to = owner;
        if (token == NATIVE) {
            (bool ok,) = to.call{value: amount}("");
            if (!ok) revert NativeTransferFailed();
        } else {
            IERC20(token).safeTransfer(to, amount);
        }
        emit Withdrawn(token, to, amount);
    }
}

contracts/ElyAccountFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {Clones} from "@openzeppelin/contracts/proxy/Clones.sol";
import {ElyAccount} from "./ElyAccount.sol";

/// @title ElyAccountFactory
/// @author Elyia
/// @notice Deploys ElyAccounts as EIP-1167 clones with CREATE2. The address depends only on
///         (owner, salt), so it can be shown and funded before deployment. Anyone may deploy an
///         account for any owner: the owner is fixed by the salt, so this grants nothing.
/// @dev No admin, no upgrade path. The implementation is created in the constructor and locked.
///      NOT AUDITED.
contract ElyAccountFactory {
    /// @notice The locked ElyAccount implementation all clones delegate to.
    address public immutable implementation;

    event AccountCreated(address indexed account, address indexed owner, bytes32 salt);

    error ZeroAddress();

    constructor() {
        implementation = address(new ElyAccount(address(this)));
    }

    /// @notice Deploy (or return the existing) account of `owner` for `salt`.
    function createAccount(address owner, bytes32 salt) external returns (address account) {
        if (owner == address(0)) revert ZeroAddress();
        bytes32 s = _salt(owner, salt);
        account = Clones.predictDeterministicAddress(implementation, s);
        if (account.code.length != 0) return account;
        Clones.cloneDeterministic(implementation, s);
        ElyAccount(payable(account)).initialize(owner);
        emit AccountCreated(account, owner, salt);
    }

    /// @notice Counterfactual address of the account of `owner` for `salt`.
    function accountAddress(address owner, bytes32 salt) external view returns (address) {
        return Clones.predictDeterministicAddress(implementation, _salt(owner, salt));
    }

    function _salt(address owner, bytes32 salt) internal pure returns (bytes32) {
        return keccak256(abi.encode(owner, salt));
    }
}

contracts/ElyiaRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {IElyiaRouter} from "./interfaces/IElyiaRouter.sol";
import {IWrappedNative, IV2Router, IV3SwapRouterV1, IV3SwapRouter02, IPermit2} from "./interfaces/IExternal.sol";

/// @title ElyiaRouter
/// @author Elyia
/// @notice Stateless multi-venue swap router for Elysium. Splits an input across routes, each route
///         a chain of hops on allowlisted venues (Uniswap V3-style routers, Uniswap V2-style routers,
///         WETH9-style wrappers). `minAmountOut` and `deadline` are enforced on the total, net of fees.
/// @dev Security model:
///      - Funds are only ever pulled from `msg.sender` (ERC-20 allowance, Permit2 signature or Permit2
///        allowance). The owner can never move a user's allowance.
///      - The router holds no funds between transactions: every entry point snapshots the balance of
///        each token it touches and reverts if any balance ends above its snapshot (`FundsLeftInRouter`).
///      - Venues are allowlisted by the owner and typed; each venue receives an exact allowance that is
///        reset to zero right after the call. Outputs are measured by balance differences, never by
///        trusting return values.
///      - Protocol fee is capped at 30 bps (default 0); integrator fees need owner registration and are
///        capped at 50 bps. Fees are pushed in the same transaction.
///      - `nonReentrant` on every state-changing entry point; `whenNotPaused` on every user flow.
///      NOT AUDITED.
contract ElyiaRouter is IElyiaRouter, Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ---------------------------------------------------------------------------------------------
    // Constants and immutables
    // ---------------------------------------------------------------------------------------------

    /// @notice Native HYPE sentinel.
    address internal constant NATIVE = address(0);
    /// @notice Amount sentinel for multicall actions: use everything this call brought into the router.
    uint256 public constant CONTRACT_BALANCE = type(uint256).max;
    /// @notice Hard cap of the protocol fee, in bps.
    uint16 public constant MAX_PROTOCOL_FEE_BPS = 30;
    /// @notice Hard cap of any integrator fee, in bps.
    uint16 public constant MAX_INTEGRATOR_FEE_BPS = 50;
    uint256 internal constant BPS = 10_000;
    /// @notice Maximum split legs per swap.
    uint256 public constant MAX_ROUTES = 8;
    /// @notice Maximum hops per leg.
    uint256 public constant MAX_HOPS = 4;
    /// @notice Maximum distinct tokens (incl. native) one call may touch.
    uint256 public constant MAX_TRACKED_TOKENS = 16;

    /// @notice Canonical Permit2.
    IPermit2 public immutable PERMIT2;

    // ---------------------------------------------------------------------------------------------
    // Storage (configuration only; the router never stores user balances)
    // ---------------------------------------------------------------------------------------------

    /// @inheritdoc IElyiaRouter
    mapping(address venue => VenueKind) public venueKind;
    /// @notice Registered integrators and their maximum fee in bps (0 = not registered).
    mapping(address integrator => uint16) public integratorMaxFeeBps;
    /// @notice Protocol fee in bps taken from the gross output. Default 0.
    uint16 public protocolFeeBps;
    /// @notice Receiver of the protocol fee.
    address public feeRecipient;

    // ---------------------------------------------------------------------------------------------
    // Multicall actions
    // ---------------------------------------------------------------------------------------------

    /// @notice Multicall operation codes. `data` encodings:
    ///  PULL                   (address token, uint256 amount)                        ERC-20 transferFrom(msg.sender)
    ///  PULL_PERMIT2           (IPermit2.PermitTransferFrom permit, uint256 amount, bytes signature)
    ///  PULL_PERMIT2_ALLOWANCE (address token, uint160 amount)
    ///  WRAP                   (address wrapper, uint256 amount | CONTRACT_BALANCE)
    ///  UNWRAP                 (address wrapper, uint256 amount | CONTRACT_BALANCE)
    ///  SWAP                   (SwapParams) - input taken from the router's in-call balance
    ///  VAULT_DEPOSIT          (address vault, uint256 assets | CONTRACT_BALANCE, address receiver, uint256 minShares)
    ///  VAULT_REDEEM           (address vault, uint256 shares | CONTRACT_BALANCE, address receiver, uint256 minAssets)
    ///  SWEEP                  (address token, address recipient, uint256 minAmount)
    enum Op {
        PULL,
        PULL_PERMIT2,
        PULL_PERMIT2_ALLOWANCE,
        WRAP,
        UNWRAP,
        SWAP,
        VAULT_DEPOSIT,
        VAULT_REDEEM,
        SWEEP
    }

    struct Action {
        Op op;
        bytes data;
    }

    /// @dev In-memory per-call ledger of touched tokens and their starting balances.
    struct Ledger {
        address[] tokens;
        uint256[] start;
        uint256 len;
    }

    // ---------------------------------------------------------------------------------------------
    // Events
    // ---------------------------------------------------------------------------------------------

    event Swap(
        address indexed sender,
        address indexed recipient,
        address indexed tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 protocolFee,
        address integrator,
        uint256 integratorFee
    );
    event Wrapped(address indexed wrapper, uint256 amount);
    event Unwrapped(address indexed wrapper, uint256 amount);
    event Pulled(address indexed from, address indexed token, uint256 amount);
    event VaultDeposited(address indexed sender, address indexed vault, address indexed receiver, uint256 assets, uint256 shares);
    event VaultRedeemed(address indexed sender, address indexed vault, address indexed receiver, uint256 shares, uint256 assets);
    event Swept(address indexed token, address indexed recipient, uint256 amount);
    event VenueSet(address indexed venue, VenueKind kind);
    event ProtocolFeeSet(uint16 feeBps, address indexed recipient);
    event IntegratorSet(address indexed integrator, uint16 maxFeeBps);
    event Rescued(address indexed token, address indexed to, uint256 amount);

    // ---------------------------------------------------------------------------------------------
    // Errors
    // ---------------------------------------------------------------------------------------------

    error DeadlineExpired();
    error ZeroAddress();
    error ZeroAmount();
    error SameToken();
    error BadRouteCount();
    error BadHopCount();
    error BrokenPath();
    error AmountMismatch();
    error VenueNotAllowed(address venue);
    error BadHop();
    error NoOutput();
    error InsufficientOutput(uint256 amountOut, uint256 minAmountOut);
    error InsufficientBalance(address token, uint256 available, uint256 needed);
    error FeeTooHigh();
    error IntegratorNotAllowed();
    error UnexpectedValue();
    error NativeTransferFailed();
    error FundsLeftInRouter(address token);
    error TooManyTokens();
    error UnexpectedNative();
    error PermitMismatch();
    error RenounceDisabled();

    // ---------------------------------------------------------------------------------------------
    // Constructor and admin
    // ---------------------------------------------------------------------------------------------

    /// @param initialOwner Owner (the deployer's wallet). Can set fees, venues, pause and rescue dust.
    /// @param permit2 Canonical Permit2 address on this chain.
    /// @param venues Initial allowlisted venues.
    /// @param kinds Kind of each initial venue.
    constructor(address initialOwner, address permit2, address[] memory venues, VenueKind[] memory kinds)
        Ownable(initialOwner)
    {
        if (permit2 == address(0)) revert ZeroAddress();
        if (venues.length != kinds.length) revert AmountMismatch();
        PERMIT2 = IPermit2(permit2);
        for (uint256 i; i < venues.length; ++i) {
            _setVenue(venues[i], kinds[i]);
        }
    }

    /// @notice Allowlist, retype or remove (`NONE`) a venue.
    function setVenue(address venue, VenueKind kind) external onlyOwner {
        _setVenue(venue, kind);
    }

    /// @notice Set the protocol fee (<= 30 bps) and its recipient.
    function setProtocolFee(uint16 feeBps, address recipient) external onlyOwner {
        if (feeBps > MAX_PROTOCOL_FEE_BPS) revert FeeTooHigh();
        if (feeBps != 0 && recipient == address(0)) revert ZeroAddress();
        protocolFeeBps = feeBps;
        feeRecipient = recipient;
        emit ProtocolFeeSet(feeBps, recipient);
    }

    /// @notice Register (maxFeeBps > 0) or unregister (0) an integrator.
    function setIntegrator(address integrator, uint16 maxFeeBps) external onlyOwner {
        if (integrator == address(0)) revert ZeroAddress();
        if (maxFeeBps > MAX_INTEGRATOR_FEE_BPS) revert FeeTooHigh();
        integratorMaxFeeBps[integrator] = maxFeeBps;
        emit IntegratorSet(integrator, maxFeeBps);
    }

    /// @notice Kill switch: stops every swap and multicall. Admin and rescue keep working.
    function pause() external onlyOwner {
        _pause();
    }

    /// @notice Lift the kill switch.
    function unpause() external onlyOwner {
        _unpause();
    }

    /// @notice Recover dust sent to the router by mistake. The router holds no user funds between
    ///         transactions, so this can only ever touch stray balances.
    function rescue(address token, address to, uint256 amount) external onlyOwner nonReentrant {
        if (to == address(0)) revert ZeroAddress();
        _send(token, to, amount);
        emit Rescued(token, to, amount);
    }

    /// @notice Renouncing is disabled so the kill switch can never be orphaned.
    function renounceOwnership() public view override onlyOwner {
        revert RenounceDisabled();
    }

    // ---------------------------------------------------------------------------------------------
    // User entry points
    // ---------------------------------------------------------------------------------------------

    /// @inheritdoc IElyiaRouter
    function swap(SwapParams calldata params)
        external
        payable
        nonReentrant
        whenNotPaused
        returns (uint256 amountOut)
    {
        Ledger memory l = _openLedger();
        SwapParams memory p = params;
        _checkSwapFunding(p);
        if (p.tokenIn != NATIVE) {
            _track(l, p.tokenIn);
            IERC20(p.tokenIn).safeTransferFrom(msg.sender, address(this), p.amountIn);
        }
        amountOut = _swap(l, p);
        _settle(l);
    }

    /// @notice Swap pulling `tokenIn` from msg.sender with a Permit2 signature (no prior approval
    ///         to this router needed). The permit owner is always msg.sender.
    function swapWithPermit2(
        SwapParams calldata params,
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature
    ) external nonReentrant whenNotPaused returns (uint256 amountOut) {
        Ledger memory l = _openLedger();
        SwapParams memory p = params;
        if (p.tokenIn == NATIVE || permit.permitted.token != p.tokenIn) revert PermitMismatch();
        _checkSwapFunding(p);
        _track(l, p.tokenIn);
        PERMIT2.permitTransferFrom(
            permit, IPermit2.SignatureTransferDetails({to: address(this), requestedAmount: p.amountIn}), msg.sender, signature
        );
        amountOut = _swap(l, p);
        _settle(l);
    }

    /// @notice Batch of actions in one transaction, e.g. native HYPE -> wrap -> swap -> ERC-4626
    ///         deposit, or Permit2 pull -> swap -> deposit. Funds only come from msg.sender (msg.value
    ///         or pulls). Everything brought in must leave by the end of the call.
    /// @param deadline Unix time after which the batch reverts.
    function multicall(uint256 deadline, Action[] calldata actions) external payable nonReentrant whenNotPaused {
        if (block.timestamp > deadline) revert DeadlineExpired();
        Ledger memory l = _openLedger();
        for (uint256 i; i < actions.length; ++i) {
            _dispatch(l, actions[i]);
        }
        _settle(l);
    }

    /// @dev Only accepts native HYPE from an allowlisted wrapper during a call (unwraps). Both storage
    ///      reads are warm at that point, so this fits in the 2300 gas stipend of WETH9's `transfer`.
    receive() external payable {
        if (!_reentrancyGuardEntered() || venueKind[msg.sender] != VenueKind.WRAPPER) revert UnexpectedNative();
    }

    // ---------------------------------------------------------------------------------------------
    // Multicall dispatch
    // ---------------------------------------------------------------------------------------------

    function _dispatch(Ledger memory l, Action calldata a) internal {
        Op op = a.op;
        if (op == Op.PULL) {
            (address token, uint256 amount) = abi.decode(a.data, (address, uint256));
            if (token == NATIVE) revert BadHop();
            if (amount == 0) revert ZeroAmount();
            _track(l, token);
            IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
            emit Pulled(msg.sender, token, amount);
        } else if (op == Op.PULL_PERMIT2) {
            (IPermit2.PermitTransferFrom memory permit, uint256 amount, bytes memory sig) =
                abi.decode(a.data, (IPermit2.PermitTransferFrom, uint256, bytes));
            if (permit.permitted.token == NATIVE) revert BadHop();
            if (amount == 0) revert ZeroAmount();
            _track(l, permit.permitted.token);
            PERMIT2.permitTransferFrom(
                permit, IPermit2.SignatureTransferDetails({to: address(this), requestedAmount: amount}), msg.sender, sig
            );
            emit Pulled(msg.sender, permit.permitted.token, amount);
        } else if (op == Op.PULL_PERMIT2_ALLOWANCE) {
            (address token, uint160 amount) = abi.decode(a.data, (address, uint160));
            if (token == NATIVE) revert BadHop();
            if (amount == 0) revert ZeroAmount();
            _track(l, token);
            PERMIT2.transferFrom(msg.sender, address(this), amount, token);
            emit Pulled(msg.sender, token, amount);
        } else if (op == Op.WRAP) {
            (address wrapper, uint256 amount) = abi.decode(a.data, (address, uint256));
            _requireVenue(wrapper, VenueKind.WRAPPER);
            if (amount == CONTRACT_BALANCE) amount = _available(l, NATIVE);
            _requireAvailable(l, NATIVE, amount);
            _track(l, wrapper);
            IWrappedNative(wrapper).deposit{value: amount}();
            emit Wrapped(wrapper, amount);
        } else if (op == Op.UNWRAP) {
            (address wrapper, uint256 amount) = abi.decode(a.data, (address, uint256));
            _requireVenue(wrapper, VenueKind.WRAPPER);
            _track(l, wrapper);
            if (amount == CONTRACT_BALANCE) amount = _available(l, wrapper);
            _requireAvailable(l, wrapper, amount);
            IWrappedNative(wrapper).withdraw(amount);
            emit Unwrapped(wrapper, amount);
        } else if (op == Op.SWAP) {
            SwapParams memory p = abi.decode(a.data, (SwapParams));
            _track(l, p.tokenIn);
            if (p.amountIn == CONTRACT_BALANCE) {
                if (p.routes.length != 1) revert BadRouteCount();
                p.amountIn = _available(l, p.tokenIn);
                p.routes[0].amountIn = p.amountIn;
            }
            _requireAvailable(l, p.tokenIn, p.amountIn);
            _swap(l, p);
        } else if (op == Op.VAULT_DEPOSIT) {
            (address vault, uint256 assets, address receiver, uint256 minShares) =
                abi.decode(a.data, (address, uint256, address, uint256));
            _vaultDeposit(l, vault, assets, receiver, minShares);
        } else if (op == Op.VAULT_REDEEM) {
            (address vault, uint256 shares, address receiver, uint256 minAssets) =
                abi.decode(a.data, (address, uint256, address, uint256));
            _vaultRedeem(l, vault, shares, receiver, minAssets);
        } else {
            // Op.SWEEP (abi decoding already rejects out-of-range enum values)
            (address token, address recipient, uint256 minAmount) = abi.decode(a.data, (address, address, uint256));
            if (recipient == address(0)) revert ZeroAddress();
            _track(l, token);
            uint256 amount = _available(l, token);
            if (amount < minAmount) revert InsufficientOutput(amount, minAmount);
            if (amount != 0) _send(token, recipient, amount);
            emit Swept(token, recipient, amount);
        }
    }

    // ---------------------------------------------------------------------------------------------
    // Swap core
    // ---------------------------------------------------------------------------------------------

    /// @dev Validates the parts of a standalone swap that depend on how funds arrive.
    function _checkSwapFunding(SwapParams memory p) internal view {
        if (p.tokenIn == NATIVE) {
            if (msg.value != p.amountIn) revert UnexpectedValue();
        } else if (msg.value != 0) {
            revert UnexpectedValue();
        }
        if (p.amountIn == CONTRACT_BALANCE) revert ZeroAmount();
    }

    function _swap(Ledger memory l, SwapParams memory p) internal returns (uint256 net) {
        if (block.timestamp > p.deadline) revert DeadlineExpired();
        if (p.recipient == address(0)) revert ZeroAddress();
        if (p.tokenIn == p.tokenOut) revert SameToken();
        if (p.amountIn == 0) revert ZeroAmount();
        uint256 nRoutes = p.routes.length;
        if (nRoutes == 0 || nRoutes > MAX_ROUTES) revert BadRouteCount();

        if (p.integrator == address(0)) {
            if (p.integratorFeeBps != 0) revert IntegratorNotAllowed();
        } else if (p.integratorFeeBps > integratorMaxFeeBps[p.integrator]) {
            revert IntegratorNotAllowed();
        }

        uint256 sum;
        for (uint256 i; i < nRoutes; ++i) {
            sum += p.routes[i].amountIn;
        }
        if (sum != p.amountIn) revert AmountMismatch();

        _track(l, p.tokenOut);
        uint256 gross;
        for (uint256 i; i < nRoutes; ++i) {
            gross += _route(l, p.routes[i], p.tokenIn, p.tokenOut);
        }

        uint256 protocolFee = (gross * protocolFeeBps) / BPS;
        uint256 integratorFee = (gross * p.integratorFeeBps) / BPS;
        net = gross - protocolFee - integratorFee;
        if (net < p.minAmountOut) revert InsufficientOutput(net, p.minAmountOut);

        if (protocolFee != 0) _send(p.tokenOut, feeRecipient, protocolFee);
        if (integratorFee != 0) _send(p.tokenOut, p.integrator, integratorFee);
        if (p.recipient != address(this)) _send(p.tokenOut, p.recipient, net);

        emit Swap(msg.sender, p.recipient, p.tokenIn, p.tokenOut, p.amountIn, net, protocolFee, p.integrator, integratorFee);
    }

    function _route(Ledger memory l, Route memory r, address tokenIn, address tokenOut) internal returns (uint256 amount) {
        uint256 nHops = r.hops.length;
        if (nHops == 0 || nHops > MAX_HOPS) revert BadHopCount();
        amount = r.amountIn;
        if (amount == 0) revert ZeroAmount();
        address current = tokenIn;
        for (uint256 i; i < nHops; ++i) {
            Hop memory h = r.hops[i];
            if (h.tokenIn != current || h.tokenIn == h.tokenOut) revert BrokenPath();
            amount = _hop(l, h, amount);
            current = h.tokenOut;
        }
        if (current != tokenOut) revert BrokenPath();
    }

    function _hop(Ledger memory l, Hop memory h, uint256 amountIn) internal returns (uint256 amountOut) {
        _track(l, h.tokenOut);
        uint256 before = _balanceOf(h.tokenOut);

        if (h.kind == HopKind.WRAP) {
            _requireVenue(h.venue, VenueKind.WRAPPER);
            if (h.tokenIn != NATIVE || h.tokenOut != h.venue || h.fee != 0) revert BadHop();
            IWrappedNative(h.venue).deposit{value: amountIn}();
        } else if (h.kind == HopKind.UNWRAP) {
            _requireVenue(h.venue, VenueKind.WRAPPER);
            if (h.tokenIn != h.venue || h.tokenOut != NATIVE || h.fee != 0) revert BadHop();
            IWrappedNative(h.venue).withdraw(amountIn);
        } else {
            if (h.tokenIn == NATIVE || h.tokenOut == NATIVE) revert BadHop();
            IERC20 tokenIn = IERC20(h.tokenIn);
            if (h.kind == HopKind.V2) {
                _requireVenue(h.venue, VenueKind.V2_ROUTER);
                if (h.fee != 0) revert BadHop();
                address[] memory path = new address[](2);
                path[0] = h.tokenIn;
                path[1] = h.tokenOut;
                tokenIn.forceApprove(h.venue, amountIn);
                IV2Router(h.venue).swapExactTokensForTokens(amountIn, 0, path, address(this), block.timestamp);
            } else if (h.kind == HopKind.V3_V1) {
                _requireVenue(h.venue, VenueKind.V3_ROUTER_V1);
                if (h.fee == 0) revert BadHop();
                tokenIn.forceApprove(h.venue, amountIn);
                IV3SwapRouterV1(h.venue).exactInputSingle(
                    IV3SwapRouterV1.ExactInputSingleParams({
                        tokenIn: h.tokenIn,
                        tokenOut: h.tokenOut,
                        fee: h.fee,
                        recipient: address(this),
                        deadline: block.timestamp,
                        amountIn: amountIn,
                        amountOutMinimum: 0,
                        sqrtPriceLimitX96: 0
                    })
                );
            } else {
                // HopKind.V3_02
                _requireVenue(h.venue, VenueKind.V3_ROUTER_02);
                if (h.fee == 0) revert BadHop();
                tokenIn.forceApprove(h.venue, amountIn);
                IV3SwapRouter02(h.venue).exactInputSingle(
                    IV3SwapRouter02.ExactInputSingleParams({
                        tokenIn: h.tokenIn,
                        tokenOut: h.tokenOut,
                        fee: h.fee,
                        recipient: address(this),
                        amountIn: amountIn,
                        amountOutMinimum: 0,
                        sqrtPriceLimitX96: 0
                    })
                );
            }
            // Never leave an allowance behind, even if the venue pulled less than approved.
            tokenIn.forceApprove(h.venue, 0);
        }

        amountOut = _balanceOf(h.tokenOut) - before;
        if (amountOut == 0) revert NoOutput();
    }

    // ---------------------------------------------------------------------------------------------
    // Vaults
    // ---------------------------------------------------------------------------------------------

    function _vaultDeposit(Ledger memory l, address vault, uint256 assets, address receiver, uint256 minShares) internal {
        _requireVenue(vault, VenueKind.VAULT);
        if (receiver == address(0)) revert ZeroAddress();
        address asset = IERC4626(vault).asset();
        if (asset == NATIVE || asset == vault) revert BadHop();
        _track(l, asset);
        _track(l, vault);
        if (assets == CONTRACT_BALANCE) assets = _available(l, asset);
        if (assets == 0) revert ZeroAmount();
        _requireAvailable(l, asset, assets);

        uint256 sharesBefore = IERC20(vault).balanceOf(receiver);
        IERC20(asset).forceApprove(vault, assets);
        IERC4626(vault).deposit(assets, receiver);
        IERC20(asset).forceApprove(vault, 0);
        uint256 shares = IERC20(vault).balanceOf(receiver) - sharesBefore;
        if (shares == 0 || shares < minShares) revert InsufficientOutput(shares, minShares);
        emit VaultDeposited(msg.sender, vault, receiver, assets, shares);
    }

    function _vaultRedeem(Ledger memory l, address vault, uint256 shares, address receiver, uint256 minAssets) internal {
        _requireVenue(vault, VenueKind.VAULT);
        if (receiver == address(0)) revert ZeroAddress();
        address asset = IERC4626(vault).asset();
        if (asset == NATIVE || asset == vault) revert BadHop();
        _track(l, vault);
        _track(l, asset);
        if (shares == CONTRACT_BALANCE) shares = _available(l, vault);
        if (shares == 0) revert ZeroAmount();
        _requireAvailable(l, vault, shares);

        uint256 assetsBefore = IERC20(asset).balanceOf(receiver);
        IERC4626(vault).redeem(shares, receiver, address(this));
        uint256 assets = IERC20(asset).balanceOf(receiver) - assetsBefore;
        if (assets == 0 || assets < minAssets) revert InsufficientOutput(assets, minAssets);
        emit VaultRedeemed(msg.sender, vault, receiver, shares, assets);
    }

    // ---------------------------------------------------------------------------------------------
    // Ledger (sweep checks)
    // ---------------------------------------------------------------------------------------------

    function _openLedger() internal view returns (Ledger memory l) {
        l.tokens = new address[](MAX_TRACKED_TOKENS);
        l.start = new uint256[](MAX_TRACKED_TOKENS);
        // Native is always tracked; msg.value is already in the balance.
        l.tokens[0] = NATIVE;
        l.start[0] = address(this).balance - msg.value;
        l.len = 1;
    }

    /// @dev Snapshots `token` the first time it is touched in this call.
    function _track(Ledger memory l, address token) internal view {
        for (uint256 i; i < l.len; ++i) {
            if (l.tokens[i] == token) return;
        }
        if (l.len == MAX_TRACKED_TOKENS) revert TooManyTokens();
        l.tokens[l.len] = token;
        l.start[l.len] = _balanceOf(token);
        ++l.len;
    }

    /// @dev Amount of `token` this call brought into the router (pre-existing dust is never usable).
    function _available(Ledger memory l, address token) internal view returns (uint256) {
        for (uint256 i; i < l.len; ++i) {
            if (l.tokens[i] == token) {
                uint256 bal = _balanceOf(token);
                return bal > l.start[i] ? bal - l.start[i] : 0;
            }
        }
        return 0;
    }

    function _requireAvailable(Ledger memory l, address token, uint256 amount) internal view {
        if (amount == 0) revert ZeroAmount();
        uint256 avail = _available(l, token);
        if (avail < amount) revert InsufficientBalance(token, avail, amount);
    }

    /// @dev Reverts if any touched token ends above its starting balance.
    function _settle(Ledger memory l) internal view {
        for (uint256 i; i < l.len; ++i) {
            if (_balanceOf(l.tokens[i]) > l.start[i]) revert FundsLeftInRouter(l.tokens[i]);
        }
    }

    // ---------------------------------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------------------------------

    function _setVenue(address venue, VenueKind kind) internal {
        if (venue == address(0) || venue == address(this)) revert ZeroAddress();
        if (kind != VenueKind.NONE && venue.code.length == 0) revert VenueNotAllowed(venue);
        venueKind[venue] = kind;
        emit VenueSet(venue, kind);
    }

    function _requireVenue(address venue, VenueKind kind) internal view {
        if (venueKind[venue] != kind) revert VenueNotAllowed(venue);
    }

    function _balanceOf(address token) internal view returns (uint256) {
        return token == NATIVE ? address(this).balance : IERC20(token).balanceOf(address(this));
    }

    function _send(address token, address to, uint256 amount) internal {
        if (token == NATIVE) {
            (bool ok,) = to.call{value: amount}("");
            if (!ok) revert NativeTransferFailed();
        } else {
            IERC20(token).safeTransfer(to, amount);
        }
    }
}

contracts/ElyOrders.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {SignatureChecker} from "@openzeppelin/contracts/utils/cryptography/SignatureChecker.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {IElyiaRouter} from "./interfaces/IElyiaRouter.sol";
import {IV3PoolOracle} from "./interfaces/IExternal.sol";

/// @title ElyOrders
/// @author Elyia
/// @notice Conditional orders for Elysium AMMs: limit, stop-loss, take-profit, DCA and TWAP.
///         Makers (EOAs or ElyAccounts via ERC-1271) sign EIP-712 orders; funds stay in the maker's
///         wallet behind an allowance to this contract. Any keeper may execute through ElyiaRouter
///         once the condition holds. Output always goes to the maker and must meet `minAmountOut`.
/// @dev Condition: an optional Uniswap V3 pool oracle. With `twapWindow > 0` the TWAP tick and the spot
///      tick must both satisfy the trigger and stay within `maxDeviationTicks` of each other (sanity
///      bound against single-block manipulation). Keeper tip is paid in `tokenIn`, at most the maker's
///      signed `maxTip` and never more than 1% of `amountIn`. No owner, no admin, no upgrade path.
///      NOT AUDITED.
contract ElyOrders is EIP712, ReentrancyGuard {
    using SafeERC20 for IERC20;

    enum OrderKind {
        LIMIT,
        STOP_LOSS,
        TAKE_PROFIT,
        DCA,
        TWAP
    }

    /// @param maker Owner of the funds and receiver of the output.
    /// @param tokenIn ERC-20 sold (native HYPE is not supported as input; use WHYPE).
    /// @param tokenOut Token bought (`address(0)` = native HYPE).
    /// @param amountIn Amount sold per execution.
    /// @param minAmountOut Minimum received per execution, net of router fees (the limit price).
    /// @param maxTip Maximum keeper tip per execution, in `tokenIn`.
    /// @param oracle Uniswap V3 pool used for the trigger, or `address(0)` for none.
    /// @param triggerTick Trigger in the oracle pool's tick space (price of token1 in token0).
    /// @param triggerAbove True: execute when tick >= triggerTick; false: when tick <= triggerTick.
    /// @param twapWindow TWAP window in seconds; 0 = spot tick only.
    /// @param maxDeviationTicks Max |spot - TWAP| allowed when `twapWindow > 0`.
    /// @param kind Order type (validated for consistency).
    /// @param executions Number of executions (1 for limit/stop/TP, >= 2 for DCA/TWAP).
    /// @param interval Minimum seconds between executions.
    /// @param startTime Earliest execution time.
    /// @param deadline Order expiry.
    /// @param nonce Maker-chosen nonce; `invalidateNonces` voids every nonce below a floor.
    struct Order {
        address maker;
        address tokenIn;
        address tokenOut;
        uint256 amountIn;
        uint256 minAmountOut;
        uint256 maxTip;
        address oracle;
        int24 triggerTick;
        bool triggerAbove;
        uint32 twapWindow;
        uint24 maxDeviationTicks;
        OrderKind kind;
        uint32 executions;
        uint32 interval;
        uint64 startTime;
        uint64 deadline;
        uint256 nonce;
    }

    struct OrderState {
        uint32 executed;
        uint64 lastExecutedAt;
        bool cancelled;
    }

    bytes32 public constant ORDER_TYPEHASH = keccak256(
        "Order(address maker,address tokenIn,address tokenOut,uint256 amountIn,uint256 minAmountOut,uint256 maxTip,address oracle,int24 triggerTick,bool triggerAbove,uint32 twapWindow,uint24 maxDeviationTicks,uint8 kind,uint32 executions,uint32 interval,uint64 startTime,uint64 deadline,uint256 nonce)"
    );

    /// @notice Hard cap of the keeper tip relative to `amountIn`.
    uint256 public constant MAX_TIP_BPS = 100;
    uint256 internal constant BPS = 10_000;
    address internal constant NATIVE = address(0);

    /// @notice The router every execution goes through.
    IElyiaRouter public immutable router;

    mapping(bytes32 orderHash => OrderState) public orderState;
    /// @notice Orders with `nonce < minNonce[maker]` are void.
    mapping(address maker => uint256) public minNonce;

    event OrderExecuted(
        bytes32 indexed orderHash,
        address indexed maker,
        address indexed keeper,
        OrderKind kind,
        uint32 execution,
        uint256 amountIn,
        uint256 amountOut,
        uint256 tip
    );
    event OrderCancelled(bytes32 indexed orderHash, address indexed maker);
    event NoncesInvalidated(address indexed maker, uint256 newMinNonce);

    error BadOrder();
    error BadSignature();
    error OrderCancelledOrInvalidated();
    error NotStarted();
    error Expired();
    error FullyExecuted();
    error TooSoon();
    error TipTooHigh();
    error ConditionNotMet();
    error OracleDeviation();
    error OracleCallFailed();
    error NotMaker();
    error NonceTooLow();
    error InsufficientOutput(uint256 amountOut, uint256 minAmountOut);
    error FundsLeft();

    constructor(IElyiaRouter router_) EIP712("ElyOrders", "1") {
        if (address(router_) == address(0)) revert BadOrder();
        router = router_;
    }

    // ---------------------------------------------------------------------------------------------
    // Maker controls
    // ---------------------------------------------------------------------------------------------

    /// @notice Cancel one order. Only the maker (for an ElyAccount: through its owner's `execute`).
    function cancel(Order calldata order) external {
        if (msg.sender != order.maker) revert NotMaker();
        bytes32 h = hashOrder(order);
        orderState[h].cancelled = true;
        emit OrderCancelled(h, msg.sender);
    }

    /// @notice Void every order of msg.sender with `nonce < newMinNonce`. Can only increase.
    function invalidateNonces(uint256 newMinNonce) external {
        if (newMinNonce <= minNonce[msg.sender]) revert NonceTooLow();
        minNonce[msg.sender] = newMinNonce;
        emit NoncesInvalidated(msg.sender, newMinNonce);
    }

    // ---------------------------------------------------------------------------------------------
    // Execution (any keeper)
    // ---------------------------------------------------------------------------------------------

    /// @notice Execute one fill of `order` through ElyiaRouter along `routes`.
    /// @param routes Keeper-chosen split routes; venues are enforced by the router's allowlist.
    /// @param tip Keeper tip in `tokenIn`, at most `order.maxTip`.
    /// @return amountOut Amount the maker received.
    function execute(
        Order calldata order,
        bytes calldata signature,
        IElyiaRouter.Route[] calldata routes,
        uint256 tip
    ) external nonReentrant returns (uint256 amountOut) {
        bytes32 h = hashOrder(order);
        OrderState memory st = orderState[h];
        _validate(order, st);
        if (!SignatureChecker.isValidSignatureNow(order.maker, _hashTypedDataV4(h), signature)) revert BadSignature();
        if (tip > order.maxTip) revert TipTooHigh();
        _checkCondition(order);

        // Effects before interactions.
        uint32 n = st.executed + 1;
        orderState[h].executed = n;
        orderState[h].lastExecutedAt = uint64(block.timestamp);

        amountOut = _fill(order, routes, tip);
        emit OrderExecuted(h, order.maker, msg.sender, order.kind, n, order.amountIn, amountOut, tip);
    }

    // ---------------------------------------------------------------------------------------------
    // Views
    // ---------------------------------------------------------------------------------------------

    /// @notice EIP-712 struct hash of `order` (the key of `orderState`).
    function hashOrder(Order calldata o) public pure returns (bytes32) {
        bytes memory a = abi.encode(
            ORDER_TYPEHASH, o.maker, o.tokenIn, o.tokenOut, o.amountIn, o.minAmountOut, o.maxTip, o.oracle, o.triggerTick
        );
        bytes memory b = abi.encode(
            o.triggerAbove,
            o.twapWindow,
            o.maxDeviationTicks,
            uint8(o.kind),
            o.executions,
            o.interval,
            o.startTime,
            o.deadline,
            o.nonce
        );
        return keccak256(bytes.concat(a, b));
    }

    /// @notice Full EIP-712 digest the maker signs.
    function orderDigest(Order calldata o) external view returns (bytes32) {
        return _hashTypedDataV4(hashOrder(o));
    }

    /// @notice EIP-712 domain separator.
    function domainSeparator() external view returns (bytes32) {
        return _domainSeparatorV4();
    }

    /// @notice Whether the price condition holds right now (does not check time, nonce or signature).
    function conditionMet(Order calldata o) external view returns (bool ok) {
        if (o.oracle == address(0)) return true;
        (bool success, int24 spot, int24 twap) = _readOracle(o);
        if (!success) return false;
        if (o.twapWindow != 0) {
            uint256 dev = spot > twap ? uint256(int256(spot) - int256(twap)) : uint256(int256(twap) - int256(spot));
            if (dev > o.maxDeviationTicks) return false;
            return _meets(o, spot) && _meets(o, twap);
        }
        return _meets(o, spot);
    }

    // ---------------------------------------------------------------------------------------------
    // Internals
    // ---------------------------------------------------------------------------------------------

    /// @dev Pulls tip + amountIn from the maker, swaps through the router to the maker, verifies.
    function _fill(Order calldata order, IElyiaRouter.Route[] calldata routes, uint256 tip)
        internal
        returns (uint256 amountOut)
    {
        IERC20 tokenIn = IERC20(order.tokenIn);
        uint256 selfBefore = tokenIn.balanceOf(address(this));
        if (tip != 0) tokenIn.safeTransferFrom(order.maker, msg.sender, tip);
        tokenIn.safeTransferFrom(order.maker, address(this), order.amountIn);

        uint256 makerBefore = _balanceOf(order.tokenOut, order.maker);
        tokenIn.forceApprove(address(router), order.amountIn);
        router.swap(_swapParams(order, routes));
        tokenIn.forceApprove(address(router), 0);

        amountOut = _balanceOf(order.tokenOut, order.maker) - makerBefore;
        if (amountOut < order.minAmountOut) revert InsufficientOutput(amountOut, order.minAmountOut);
        if (tokenIn.balanceOf(address(this)) != selfBefore) revert FundsLeft();
    }

    function _swapParams(Order calldata order, IElyiaRouter.Route[] calldata routes)
        internal
        view
        returns (IElyiaRouter.SwapParams memory p)
    {
        p.tokenIn = order.tokenIn;
        p.tokenOut = order.tokenOut;
        p.amountIn = order.amountIn;
        p.minAmountOut = order.minAmountOut;
        p.recipient = order.maker;
        p.deadline = block.timestamp;
        p.routes = routes;
    }

    function _validate(Order calldata o, OrderState memory st) internal view {
        if (o.maker == address(0) || o.tokenIn == NATIVE || o.tokenIn == o.tokenOut) revert BadOrder();
        if (o.amountIn == 0 || o.minAmountOut == 0 || o.executions == 0) revert BadOrder();
        if (o.maxTip * BPS > o.amountIn * MAX_TIP_BPS) revert TipTooHigh();
        if (o.kind == OrderKind.STOP_LOSS || o.kind == OrderKind.TAKE_PROFIT) {
            if (o.oracle == address(0) || o.executions != 1) revert BadOrder();
        } else if (o.kind == OrderKind.LIMIT) {
            if (o.executions != 1) revert BadOrder();
        } else {
            // DCA / TWAP
            if (o.executions < 2 || o.interval == 0) revert BadOrder();
        }
        if (o.oracle == address(0) && (o.twapWindow != 0 || o.triggerTick != 0)) revert BadOrder();

        if (st.cancelled || o.nonce < minNonce[o.maker]) revert OrderCancelledOrInvalidated();
        if (block.timestamp < o.startTime) revert NotStarted();
        if (block.timestamp > o.deadline) revert Expired();
        if (st.executed >= o.executions) revert FullyExecuted();
        if (st.executed != 0 && block.timestamp < uint256(st.lastExecutedAt) + o.interval) revert TooSoon();
    }

    function _checkCondition(Order calldata o) internal view {
        if (o.oracle == address(0)) return;
        (bool success, int24 spot, int24 twap) = _readOracle(o);
        if (!success) revert OracleCallFailed();
        if (o.twapWindow != 0) {
            uint256 dev = spot > twap ? uint256(int256(spot) - int256(twap)) : uint256(int256(twap) - int256(spot));
            if (dev > o.maxDeviationTicks) revert OracleDeviation();
            if (!_meets(o, twap)) revert ConditionNotMet();
        }
        if (!_meets(o, spot)) revert ConditionNotMet();
    }

    function _meets(Order calldata o, int24 tick) internal pure returns (bool) {
        return o.triggerAbove ? tick >= o.triggerTick : tick <= o.triggerTick;
    }

    /// @dev Reads spot tick from slot0 (first two words, tolerant of fork variants) and the TWAP tick.
    function _readOracle(Order calldata o) internal view returns (bool ok, int24 spot, int24 twap) {
        (bool s0, bytes memory r0) = o.oracle.staticcall(abi.encodeWithSelector(0x3850c7bd)); // slot0()
        if (!s0 || r0.length < 64) return (false, 0, 0);
        (, int256 t) = abi.decode(r0, (uint256, int256));
        if (t < type(int24).min || t > type(int24).max) return (false, 0, 0);
        spot = int24(t);
        if (o.twapWindow == 0) return (true, spot, spot);

        uint32[] memory ago = new uint32[](2);
        ago[0] = o.twapWindow;
        ago[1] = 0;
        try IV3PoolOracle(o.oracle).observe(ago) returns (int56[] memory cum, uint160[] memory) {
            if (cum.length != 2) return (false, 0, 0);
            int56 delta = cum[1] - cum[0];
            int56 window = int56(uint56(o.twapWindow));
            int56 avg = delta / window;
            if (delta < 0 && (delta % window != 0)) avg--;
            if (avg < type(int24).min || avg > type(int24).max) return (false, 0, 0);
            return (true, spot, int24(avg));
        } catch {
            return (false, 0, 0);
        }
    }

    function _balanceOf(address token, address who) internal view returns (uint256) {
        return token == NATIVE ? who.balance : IERC20(token).balanceOf(who);
    }
}

